+static gboolean check_hec(guint8 uap, guint32 header)
+{
+    static const guint32 crc_poly_rev_bt_hec = 0xe5;
+    header &= 0x3ffff;
+    header ^= reverse_bits(uap) & 0xff;
+    for (guint i = 0; i < 10; ++i, header >>= 1)
+        if (header & 1)
+            header ^= (crc_poly_rev_bt_hec << 1);
+    return !header;
+}
